__NUXT_JSONP__("/tr/hollywood", (function(a){return {data:[{details:{slug:a,pageTitle:"Hollywood Kampüsü | Mentor Language Institute",pageDescription:"Hollywood, eğlence endüstrisinin kalbi olarak bilinir. Oscar ödüllü töreninin yanı sıra birçok film prömiyeri, Dolby tiyatrosunda , Hollywood kampüsümüze sadece 2 dakika uzaklikda ev sahipliği yapıyor.",title:"Hollywood Kampüsü",image:"\u002Fimages\u002Flocation\u002Fhollywood\u002Fhollywood-campus.jpg",yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FR9QsXd0-Cw8",subtitle:["\u003Cspan class=\"hutoaka\"\u003EHollywood, eğlence endüstrisinin kalbi olarak bilinir.\u003C\u002Fspan\u003E Oscar ödüllü töreninin yanı sıra birçok film prömiyeri, Dolby tiyatrosunda , Hollywood kampüsümüze sadece 2 dakika uzaklikda ev sahipliği yapıyor. Muhtemelen Dolby Theatre'ın dışındaki alanda limuzinden inen bir Hollywood film yıldızın göreceksiniz!","Hollywood öğrencilerimiz, Dans, Müzik, Oyunculuk, Film, Yoga vb. Eğlencelerle ilgilenmeye eğilimlidirler. Ünlü Musician’ın enstitüsü, Hollywood kampüsümüzün tam karşısındadır.","Bölgede ayrıca birçok dans stüdyosu bulunmaktadır:"],lists:["Müzisyen Enstitüsü","Kenar Sahne Sanatları","Milenyum Dans Kompleksi","Debbie Raynolds","MovementLifestyle","Los Angeles Film Okulu","NY Film Akademisi"],other_desc:["Hollywood'un elverişli konumu, genellikle toplu taşıma araçlarına bel bağlayan uluslararası öğrenciler için mükemmeldir (Hollywood ve Highland durağı kampüse sadece 2 dakikalık yürüme mesafesindedir.)","Küçük bir sınıf ortamında eğitim almak ve eğlence \u002F film \u002F müzik endüstrisine yakın olmak isterseniz, lütfen MLI-Hollywood'da bize katılın!"],albums:[{title:"Kampüs",photos:["\u002Fimages\u002Flocation\u002Fhollywood\u002Fcampus-1.jpg","\u002Fimages\u002Flocation\u002Fhollywood\u002Fcampus-2.jpg"]},{title:"Sınıf",photos:["\u002Fimages\u002Flocation\u002Fhollywood\u002Fclass-1.jpg","\u002Fimages\u002Flocation\u002Fhollywood\u002Fclass-2.jpg"]}],location:{title:"Konum",link:"https:\u002F\u002Fwww.google.com\u002Fmaps\u002Fembed?pb=!1m18!1m12!1m3!1d3303.7636753752786!2d-118.3467233847837!3d34.1011940805926!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x80c2bf239f1c4a45%3A0x6953aa45bd461a42!2sMentor%20Language%20Institute%20-%20Hollywood!5e0!3m2!1sen!2sph!4v1576725075448!5m2!1sen!2sph"},video:[{title:"1. Hollywood Highland Tren İstasyonu üzerinden MLI Hollywood Kampüsü'ne nasıl gidilir?",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FrP3AV1P3duU"},{title:"2. Araçla MLI Hollywood Kampüsüne Nasıl Gidilir? \u003Cbr \u002F\u003E\u003Cbr \u002F\u003E",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FJO2iqyI9Dfc"}],accommodation:{title:"Konaklama",description:["Konaklamalarınız için Aile yani ve yurt sağlamaktayız.","＜Yurt＞\u003Cbr\u002F\u003E","Yurtlarımız, okula yakın elverişli yerlerde bulunmaktadır."],information:[{yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002F27o22DzbFp0",desc:["＜Aile Yani＞ \u003Cbr\u002F\u003E","Aile yanı, Amerikan kültürü hakkında bilgi edinmenin ve İngilizce konuşma fırsatlarınızı artırmanın en iyi yoludur.","\u003Ca href=\"\u002Ftr\u002Fstay\u002F\"\u003E\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E Konaklama hakkında daha fazla bilgi\u003C\u002Fa\u003E"]}]},courses:{title:"Dersler",lists:["ESL Programı","TOEFL®","Konuşma Programı","TOEIC®"]},message:{title:"Hollywood Kampüsünden Mesaj",image:"\u002Fimages\u002Flocation\u002Fhollywood\u002Fjulie.jpg",position:"Kampüs Direktörünün Mesajı",description:["MLI Hollywood kampüsü, Hollywood'un hareketli merkezinde, Hollywood \u002F Highland metro istasyonuna sadece 2 dakikalık yürüme mesafesinde yer almaktadır. Dolby Tiyatrosu, Çin Tiyatrosu ve Walk of Fame, Hollywood'un kampüsünün hemen yanında eğlenmek için birçok fırsat sunuyor!"]},dir:"\u002Fhollywood",path:"\u002Fhollywood\u002Ftr",extension:".json",createdAt:"2026-10-22T16:31:29.576Z",updatedAt:"2025-05-26T12:06:27.781Z"},lang:a}],fetch:{},mutations:void 0}}("tr")));